   "file": "sdks/python/examples/train_and_deploy.py",
   "title": "Snapshot data, train a DGSR model, review it and put it into service.",
   "code": "\"\"\"Snapshot data, train a DGSR model, review it and put it into service.\n\nexport GRAPHREC_ADMIN_EMAIL=owner@acme.example GRAPHREC_ADMIN_PASSWORD=...\npython examples/train_and_deploy.py\n\"\"\"\n\nfrom __future__ import annotations\n\nimport contextlib\nimport os\n\nfrom graphrec_sdk import GraphRec, StateConflictError\n\nMIN_NDCG = 0.5\n\n\ndef main() -> None:\n    with GraphRec(\n        email=os.environ[\"GRAPHREC_ADMIN_EMAIL\"], password=os.environ[\"GRAPHREC_ADMIN_PASSWORD\"]\n    ) as admin:\n        snapshot = admin.tenant.datasets.create_snapshot()\n        print(\n            f\"snapshot {snapshot.id}: {snapshot.event_count} events, \"\n            f\"{snapshot.product_count} products, {snapshot.user_count} users\"\n        )\n\n        job = admin.tenant.training_jobs.create(\n            dataset_snapshot_id=snapshot.id,\n            configuration={\"batch_size\": 256, \"learning_rate\": 0.001, \"gnn_layers\": 2},\n        )\n        job = admin.tenant.training_jobs.wait(job.id, timeout=1800, poll_interval=10)\n        if not job.succeeded or job.model_version_id is None:\n            raise SystemExit(f\"training {job.status}: {job.failure_reason}\")\n\n        candidate = admin.tenant.model_versions.get(job.model_version_id)\n        previous = admin.tenant.model_versions.get_active()\n        print(f\"candidate {candidate.version_tag}: {candidate.metrics or 'no offline metrics'}\")\n        ndcg = candidate.tenant.metrics.get(\"ndcg_at_10\")\n        if ndcg is not None and float(ndcg) < MIN_NDCG:\n            raise SystemExit(f\"ndcg@10 {float(ndcg):.3f} below threshold - not activating\")\n        if ndcg is None:\n            # The current training slice indexes placeholder embeddings and reports no metrics.\n            print(\"warning: no ndcg_at_10 reported; activating without a quality gate\")\n\n        admin.tenant.model_versions.activate(candidate.id)\n        status = admin.tenant.deployment.get()\n        print(f\"deployment {status.status}, serving {status.active_model_version_id}\")\n\n        metrics = admin.tenant.metrics.summary()\n        # error_rate is None until the new version has served a request.\n        if previous is not None and (metrics.error_rate or 0) > 0.05:\n            print(\"error rate too high, rolling back\")\n            admin.tenant.model_versions.rollback(previous.id)\n\n        for version in admin.tenant.model_versions.list():\n            if version.status == \"retired\":\n                with contextlib.suppress(StateConflictError):\n                    admin.tenant.model_versions.archive(version.id)\n\n\nif __name__ == \"__main__\":\n    main()\n"
